15:fn main() {
96:    if o.stage("sky", &mut c, &mut rng) {
157:    if o.stage("moon", &mut c, &mut rng) {
209:    if o.stage("far", &mut c, &mut rng) {
221:    if o.stage("ridge", &mut c, &mut rng) {
289:    if o.stage("ruin", &mut c, &mut rng) {
340:    if o.stage("mist", &mut c, &mut rng) {
355:    if o.stage("snow", &mut c, &mut rng) {
479:    if o.stage("brook", &mut c, &mut rng) {
