    /// Dead wood, if it should differ (weathered grey).
    pub dead: Option<Paint>,
    /// Lean light for the lit side of the big limbs (dry-brushed).
    pub light: Option<Paint>,
    /// Pale fresh wood showing at a break.
    pub wood: Option<Paint>,
