/// A whole number in lo..hi (hi excluded).
fn ri(rng: &mut Rng, lo: i64, hi: i64) -> i64 {
    if hi <= lo { lo } else { lo + ((rng.f() * (hi - lo) as f32) as i64).min(hi - lo - 1) }
}
